import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/92-有效沟通的必要性.md","filePath":"books/attached/92-有效沟通的必要性.md","lastUpdated":1794316978000}'),l={name:"books/attached/92-有效沟通的必要性.md"};function n(d,a,_,c,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"有效沟通的必要性",tabindex:"-1"},[s("有效沟通的必要性 "),e("a",{class:"header-anchor",href:"#有效沟通的必要性","aria-label":'Permalink to "有效沟通的必要性"'},"​")],-1),e("p",null,"下面是有效沟通的两个主要目标：",-1),e("p",null,"-找到合适的伴侣。为了确定未来伴侣是否有能力满足你的亲密需求，有效沟通可以说是最为快捷、直接的方式了。而对于有效沟通的回应，则可以在五分钟之内就揭示出比缺乏沟通接触一个月还要多的真相。若是对方对于你的需求回应很真诚，并十分在意你的快乐，你们的未来就会很有希望。若是对方对于你的诉求顾左右而言他，毫不在意。抑或是视你的感受为愚不可及、不合时宜或是自我放纵。这时候你就应该清楚，这个人没有认真地把你的感受放在心上，你们俩就可能不太适合。",-1),e("p",null,"-确认这段关系的确符合你的亲密需求，不论是刚开始交往还是交往已久。勇敢说出你的需求，有助于伴侣了解你的想法，并且尝试满足你的需求。他将不再需要事事揣测，担心什么事会困扰到你，甚至要去猜“这些事情”到底是指什么？",-1),e("p",null,"有效沟通的美妙之处就在于，它有可能将你曾以为的砒霜，转化为蜜糖，让你在亲密关系中摆脱被动。起码在恋爱的最初阶段，你如果的确需要一再确定对方是不是爱你，那就勇敢地说出来。而不要因为对表现出自己的依赖感而有所顾忌，感觉自己在倒贴，从而打消这种念头。只要将自己的依恋表达出来，你并不会成为弱势，反而可以建立起自信，获得安心。当然，有效沟通的意思是，你沟通的方式不会充满攻击性，不会激怒对方，不让他感觉到深陷责备，而同时又让他放下戒备，对你敞开心扉。",-1),e("p",null,"而有效沟通的另一个好处就是，你为你的伴侣做出了良好的榜样。你首先表现出自己在这段关系中的坦诚，并表示愿意为了对方的幸福承担起责任，甚至做一点牺牲。而你的伴侣看到你如此坦率，他们也会跟随你的步伐。正如第8章提到的那样，有心使用有效沟通来促进亲密关系，什么时候开始都不算晚。这是安全型依恋风格的人们惯常使用的最有力武器，无论是对待伴侣和子女，还是对待工作，他们都是如此。养成有效沟通的习惯，真的可以为你自己的为人处事方式，带来很大的转变。",-1)])])}const f=t(l,[["render",n]]);export{u as __pageData,f as default};
